function mulberry32(seed: number) { return () => { let t = (seed += 0x6d2b79f5); t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function gaussian(rand: () => number) { const u = Math.max(rand(), 1e-9), v = Math.max(rand(), 1e-9); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); }

const testBlueprints = [
  [120101, "ACC_X_OFFSET_25C", "mg", -25, 25, 1.1, 7.2], [120102, "ACC_Y_OFFSET_25C", "mg", -25, 25, -0.8, 7.6],
  [120103, "ACC_Z_OFFSET_25C", "mg", -25, 25, 2.3, 8.1], [120220, "GYRO_RMS_NOISE_800HZ", "mdps/√Hz", 0, 18, 7.8, 2.7],
  [120315, "GYRO_X_SENSITIVITY", "LSB/dps", 28.5, 37.5, 32.7, 1.25], [130104, "VDD_CURRENT_ACTIVE", "mA", 0, 7.5, 4.42, 0.72],
  [130120, "GPIOD0_VOH", "V", 1.62, 1.9, 1.781, 0.038], [140010, "PLL_LOCK_TIME", "µs", 0, 85, 42.4, 10.5],
  [150240, "OTP_CRC_CHECK", "code", 1, 1, 1, 0], [160072, "TEMP_SENSOR_ROOM", "°C", 21, 31, 25.2, 1.3],
] as const;

function createDemoRun(): RunData {
  const rand = mulberry32(93000);
  const tests: TestData[] = testBlueprints.map(([id, name, unit, low, high]) => ({ id, name, unit, low, high, values: [] }));
  const parts: PartData[] = [], coords: Array<[number, number]> = [];
  for (let y = -15; y <= 15; y++) for (let x = -15; x <= 15; x++) if (x*x+y*y<=230 && !(y===-15&&Math.abs(x)<3)) coords.push([x,y]);
  coords.slice(0, 696).forEach(([x,y], index) => {
    const site=(index%16)+1, values:Record<number,number>={}; let partPass=true, failTest=0;
    tests.forEach((test, testIndex) => {
      const [, , , low, high, mean, sigma]=testBlueprints[testIndex]; const radial=Math.sqrt(x*x+y*y)/16;
      const siteShift=((site-8.5)/8)*.55*sigma, edgeShift=testIndex===3?radial*1.2:testIndex===5?radial*.18:0;
      let value=testIndex===8?1:mean+gaussian(rand)*sigma+siteShift+edgeShift;
      if(rand()<.007&&testIndex<8)value+=(rand()>.5?1:-1)*sigma*5.2;
      const pass=value>=low&&value<=high; if(!pass&&partPass)failTest=test.id; partPass=partPass&&pass; values[test.id]=value;
      test.values.push({value,site,partIndex:index,pass,x,y});
    });
    const hardBin=partPass?1:failTest===120220?3:failTest===130120?6:failTest===150240?8:5;
    parts.push({index,site,hardBin,softBin:hardBin,pass:partPass,x,y,testTimeMs:212+gaussian(rand)*13,values,firstFailTestId:failTest||null});
  });
  return { fileName:"DEMO_IMU_CP1_W01_20260101.stdf.gz", fileSize:48_300_000, lotId:"DEMO_LOT_001", device:"IMU-DEMO-A1", program:"demo_cp1_v1.0", tester:"ATE-DEMO-01", startTime:new Date("2026-01-01T09:00:00+08:00"), finishTime:new Date("2026-01-01T09:49:38+08:00"), waferId:"W01", tests, parts, source:"demo", waferGeometry:{waferSize:200,dieWidth:1.4,dieHeight:1.1,units:4} };
}

function percentileFromSorted(sorted:number[],p:number){if(!sorted.length)return NaN;const index=(sorted.length-1)*p,lo=Math.floor(index),hi=Math.ceil(index);return sorted[lo]+(sorted[hi]-sorted[lo])*(index-lo)}
function percentile(values:number[],p:number){return percentileFromSorted(values.filter(Number.isFinite).sort((a,b)=>a-b),p)}
function formatNumber(value:number,digits=2){if(!Number.isFinite(value))return"—";if(Math.abs(value)>=1000)return value.toLocaleString("en-US",{maximumFractionDigits:0});return value.toLocaleString("en-US",{maximumFractionDigits:digits})}
function yieldOf(run:RunData){return run.parts.filter(p=>p.pass).length/Math.max(run.parts.length,1)}
function linearCorrelation(pairs:Array<{x:number;y:number}>):CorrelationResult{const clean=pairs.filter(pair=>Number.isFinite(pair.x)&&Number.isFinite(pair.y)),n=clean.length;if(n<2)return{r:null,r2:null,slope:null,intercept:null,n,meanX:0,meanY:0};const meanX=clean.reduce((sum,pair)=>sum+pair.x,0)/n,meanY=clean.reduce((sum,pair)=>sum+pair.y,0)/n;let sxx=0,syy=0,sxy=0;clean.forEach(pair=>{const dx=pair.x-meanX,dy=pair.y-meanY;sxx+=dx*dx;syy+=dy*dy;sxy+=dx*dy});if(!sxx||!syy)return{r:null,r2:null,slope:null,intercept:null,n,meanX,meanY};const slope=sxy/sxx,r=sxy/Math.sqrt(sxx*syy);return{r,r2:r*r,slope,intercept:meanY-slope*meanX,n,meanX,meanY}}










function matchesNumericFilter(value:number,expression:string){
  const query=expression.trim();if(!query)return true;
  const comparison=query.match(/^(<=|>=|<|>)\s*(-?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?)$/i);
  if(comparison){const target=Number(comparison[2]);return comparison[1]==="<="?value<=target:comparison[1]===">="?value>=target:comparison[1]==="<"?value<target:value>target}
  const range=query.split("..");if(range.length===2){const low=Number(range[0]),high=Number(range[1]);return Number.isFinite(low)&&Number.isFinite(high)&&value>=Math.min(low,high)&&value<=Math.max(low,high)}
  const exact=Number(query);return Number.isFinite(exact)&&value===exact;
}
function filterMeasurementRows(test:TestData,site:number|"all",filters:RawColumnFilters):RawRow[]{
  const valueMin=filters.valueMin.trim()===""?null:Number(filters.valueMin),valueMax=filters.valueMax.trim()===""?null:Number(filters.valueMax),unitQuery=filters.unit.trim().toLowerCase();
  return test.values.map((measurement,index)=>({measurement,sequence:index+1})).filter(({measurement,sequence})=>(site==="all"||measurement.site===site)&&matchesNumericFilter(sequence,filters.sequence)&&matchesNumericFilter(measurement.partIndex+1,filters.part)&&matchesNumericFilter(measurement.x,filters.x)&&matchesNumericFilter(measurement.y,filters.y)&&(filters.site==="all"||measurement.site===Number(filters.site))&&(valueMin===null||Number.isFinite(valueMin)&&measurement.value>=valueMin)&&(valueMax===null||Number.isFinite(valueMax)&&measurement.value<=valueMax)&&(!unitQuery||(test.unit||"—").toLowerCase().includes(unitQuery))&&(filters.result==="all"||(filters.result==="pass")===measurement.pass))
}
function activeRawFilterCount(filters:RawColumnFilters){return [filters.sequence,filters.part,filters.x,filters.y,filters.site==="all"?"":filters.site,filters.valueMin||filters.valueMax,filters.unit,filters.result==="all"?"":filters.result].filter(Boolean).length}

function RawDataTable({test,rows,filters,setFilters,clearFilters,totalRows}:{test:TestData;rows:RawRow[];filters:RawColumnFilters;setFilters:(filters:RawColumnFilters)=>void;clearFilters:()=>void;totalRows:number}){
  const[page,setPage]=useState(0),pageSize=100,sites=[...new Set(test.values.map(value=>value.site))].sort((a,b)=>a-b),activeCount=activeRawFilterCount(filters);
  const update=<K extends keyof RawColumnFilters>(key:K,value:RawColumnFilters[K])=>{setFilters({...filters,[key]:value});setPage(0)};
  const pageCount=Math.max(1,Math.ceil(rows.length/pageSize)),safePage=Math.min(page,pageCount-1),pageRows=rows.slice(safePage*pageSize,(safePage+1)*pageSize);
  return <section className="raw-data" aria-label={`Raw data for ${test.name}`}>
    <div className="raw-toolbar"><div className="raw-filter-message"><Icon name="filter" size={16}/><div><b>Column filters</b><span>Filters update every plot and statistic, including Distribution.</span></div></div><div className="raw-count"><b>{rows.length.toLocaleString("en-US")} / {totalRows.toLocaleString("en-US")}</b><span>records</span></div><button className="raw-clear" onClick={clearFilters} disabled={!activeCount}>Clear all filters</button></div>
    <div className="raw-table-wrap"><table><thead><tr><th>Sequence</th><th>Part</th><th>Die X</th><th>Die Y</th><th>Site</th><th>Value</th><th>Unit</th><th>Result</th></tr><tr className="raw-filter-row"><th><input value={filters.sequence} onChange={event=>update("sequence",event.target.value)} placeholder="1..100" aria-label="Filter sequence column"/></th><th><input value={filters.part} onChange={event=>update("part",event.target.value)} placeholder="Exact / range" aria-label="Filter part column"/></th><th><input value={filters.x} onChange={event=>update("x",event.target.value)} placeholder="-5..5" aria-label="Filter die X column"/></th><th><input value={filters.y} onChange={event=>update("y",event.target.value)} placeholder="-5..5" aria-label="Filter die Y column"/></th><th><select value={filters.site} onChange={event=>update("site",event.target.value)} aria-label="Filter site column"><option value="all">All</option>{sites.map(value=><option value={value} key={value}>S{value}</option>)}</select></th><th><div className="raw-value-filter"><input type="number" step="any" value={filters.valueMin} onChange={event=>update("valueMin",event.target.value)} placeholder="Min" aria-label="Minimum value filter"/><input type="number" step="any" value={filters.valueMax} onChange={event=>update("valueMax",event.target.value)} placeholder="Max" aria-label="Maximum value filter"/></div></th><th><input value={filters.unit} onChange={event=>update("unit",event.target.value)} placeholder="Unit" aria-label="Filter unit column"/></th><th><select value={filters.result} onChange={event=>update("result",event.target.value as RawColumnFilters["result"])} aria-label="Filter result column"><option value="all">All</option><option value="pass">PASS</option><option value="fail">FAIL</option></select></th></tr></thead><tbody>{pageRows.map(({measurement:row,sequence})=><tr key={`${sequence}-${row.partIndex}-${row.site}`}><td>{sequence}</td><td>{row.partIndex+1}</td><td>{row.x}</td><td>{row.y}</td><td>S{row.site}</td><td><b>{formatNumber(row.value,6)}</b></td><td>{test.unit||"—"}</td><td><span className={`raw-result ${row.pass?"pass":"fail"}`}>{row.pass?"PASS":"FAIL"}</span></td></tr>)}</tbody></table>{!pageRows.length&&<div className="raw-empty">No records match the current column filters.</div>}</div>
    <div className="raw-pagination"><span>Rows {rows.length?`${safePage*pageSize+1}–${Math.min((safePage+1)*pageSize,rows.length)}`:"0"} of {rows.length.toLocaleString("en-US")}</span><div><button disabled={safePage===0} onClick={()=>setPage(Math.max(0,safePage-1))}>Previous</button><b>{safePage+1} / {pageCount}</b><button disabled={safePage>=pageCount-1} onClick={()=>setPage(Math.min(pageCount-1,safePage+1))}>Next</button></div></div>
  </section>
}

function csvCell(value:string|number){const text=String(value??"");return /[",\n]/.test(text)?`"${text.replace(/"/g,'""')}"`:text}
function downloadText(fileName:string,content:string,mime="text/csv;charset=utf-8"){
  const url=URL.createObjectURL(new Blob([content],{type:mime})),anchor=document.createElement("a");anchor.href=url;anchor.download=fileName;anchor.style.display="none";document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function exportRun(run:RunData){const sites=[...new Set(run.parts.map(part=>part.site))].sort((a,b)=>a-b),rows=[["Metric","Value"],["File",run.fileName],["Lot",run.lotId],["Wafer",run.waferId],["Device",run.device],["Tester",run.tester],["Parts",run.parts.length],["PRR pass rate",`${(yieldOf(run)*100).toFixed(4)}%`],["Tests",run.tests.length],["Sites",sites.join(" | ")]];downloadText(`${run.lotId}_${run.waferId}_summary.csv`,rows.map(row=>row.map(csvCell).join(",")).join("\n"));trackUsageFeature("export_summary")}
