type TestExplorerProps={summaries:Map<number,ReturnType<typeof stats>>;run:RunData;test:TestData;testStats:ReturnType<typeof stats>;filteredTests:TestData[];search:string;setSearch:(v:string)=>void;selectedTestId:number;setSelectedTestId:(v:number)=>void;sites:number[];site:number|"all";setSite:(v:number|"all")=>void;plot:PlotKey;setPlot:(v:PlotKey)=>void;setView:(v:ViewKey)=>void;testFilter:TestFilter;setTestFilter:(v:TestFilter)=>void};
function EnhancedTestExplorer({run,summaries,test,filteredTests,search,setSearch,setSelectedTestId,sites,site,setSite,plot,setPlot,testFilter,setTestFilter}:TestExplorerProps){
  const [distributionByTest,setDistributionByTest]=useState<Record<number,DistributionState>>({});
  const [filtersByTest,setFiltersByTest]=useState<Record<number,RawColumnFilters>>({});
  const [advanced,setAdvanced]=useState(false);
  const rawFilters=filtersByTest[test.id]??emptyRawFilters;
  const scopedTest=useMemo(()=>site==="all"?test:{...test,values:test.values.filter(value=>value.site===site)},[test,site]);
  const filteredRows=useMemo(()=>filterMeasurementRows(test,site,rawFilters),[test,site,rawFilters]);
  const filteredTest=useMemo(()=>({...test,values:filteredRows.map(row=>row.measurement)}),[test,filteredRows]);
  const activeFilterCount=activeRawFilterCount(rawFilters);
  const setRawFilters=(next:RawColumnFilters)=>setFiltersByTest(previous=>({...previous,[test.id]:next}));
  const clearRawFilters=()=>setFiltersByTest(previous=>({...previous,[test.id]:emptyRawFilters}));
  return <section className="page-content test-page focused-test-page">
    <AnalysisWorkspace run={run} tests={filteredTests} selectedTest={test} filteredTest={filteredTest}
      summaries={summaries} site={site} sites={sites} onSiteChange={setSite}
      onSelectTest={setSelectedTestId} search={search} onSearchChange={setSearch}
      testFilter={testFilter} onTestFilterChange={setTestFilter}
      distributionState={distributionByTest[test.id]}
      onDistributionChange={next=>setDistributionByTest(previous=>({...previous,[test.id]:next}))}
      onExport={values=>exportTest({...filteredTest,values})}
      activeChart={plot==="raw"?"distribution":plot} onChartChange={id=>setPlot(id as PlotKey)}
      chartViews={[
        {id:"trend",label:"Sequence",content:<TrendPlot test={filteredTest}/>,note:`First ${Math.min(500,filteredTest.values.filter(value=>Number.isFinite(value.value)).length).toLocaleString("en-US")} numeric records in filtered order. Statistics below use all filtered numeric records.`},
        {id:"site",label:"By site",content:<SiteBoxPlot test={filteredTest} selectedSite="all"/>,note:"Numeric records grouped by site. Whiskers: 10th–90th percentile."},
        {id:"cdf",label:"CDF",content:<CdfPlot test={filteredTest}/>,note:"Cumulative distribution of all filtered numeric records."}
      ]}
      toolbarChildren={activeFilterCount>0&&<span className="workspace-filter-badge">{activeFilterCount} column filters <button type="button" onClick={clearRawFilters}>Clear</button></span>}/>
    <details className="workspace-advanced" open={advanced} onToggle={event=>setAdvanced(event.currentTarget.open)}>
      <summary>Raw data &amp; column filters{activeFilterCount>0?` · ${activeFilterCount} active column filters`:""}</summary>
      {advanced&&<div className="main-plot raw-plot"><RawDataTable key={test.id} test={test} rows={filteredRows} filters={rawFilters} setFilters={setRawFilters} clearFilters={clearRawFilters} totalRows={scopedTest.values.length}/></div>}
    </details>
  </section>;
}

function EnhancedComparePage({run,history,openFiles,setSelectedTestId,setView}:{run:RunData;history:RunData[];openFiles:()=>void;setSelectedTestId:(v:number)=>void;setView:(v:ViewKey)=>void}){
  const [baselineIndex,setBaselineIndex]=useState(0),[focusedTestId,setFocusedTestId]=useState<number|null>(null),[showCorrelation,setShowCorrelation]=useState(false);
  const baseline=history[Math.min(baselineIndex,Math.max(0,history.length-1))];
  const comparisons=useMemo(()=>{
    const previousById=new Map(baseline?.tests.map(item=>[item.id,item]));
    return run.tests.map(test=>{const previous=previousById.get(test.id),currentStats=stats(test),compatible=previous&&previous.unit.trim()===test.unit.trim(),previousStats=compatible?stats(previous):null;
      return {test,previous,currentStats,previousStats,delta:previousStats?currentStats.mean-previousStats.mean:null};});
  },[run,baseline]);
  const focused=comparisons.find(item=>item.test.id===focusedTestId)??comparisons[0];
  const pairing=useMemo(()=>showCorrelation&&focused?getRunComparisonPairs(run,baseline,focused.test,focused.previous):null,[showCorrelation,run,baseline,focused]);
  const correlation=useMemo(()=>linearCorrelation(pairing?.pairs??[]),[pairing]);
  return <section className="page-content compare-page simplified-compare">
    <div className="section-title"><div><h1>Compare runs</h1><p>Choose a baseline, then compare the same test.</p></div><button className="upload-button" onClick={openFiles}><Icon name="upload"/>Add STDF runs</button></div>
    <div className="comparison-selection"><span>Current: <b>{run.fileName}</b></span><label>Baseline <select aria-label="Comparison baseline" value={baselineIndex} disabled={!history.length} onChange={event=>setBaselineIndex(Number(event.target.value))}>{history.length?history.map((item,index)=><option key={index} value={index}>{item.fileName} · {item.lotId} / {item.waferId}</option>):<option value={0}>Load another run</option>}</select></label></div>
    <article className="panel comparison-table"><div className="panel-head"><h2>Run summary</h2><button className="secondary-button" onClick={()=>exportRuns(baseline?[run,baseline]:[run])}><Icon name="download"/>Export CSV</button></div><div className="table-wrap"><table><thead><tr><th>Run</th><th>Lot / Wafer</th><th>PRR records</th><th>PRR pass rate</th><th>Failed records</th></tr></thead><tbody>{[run,...(baseline?[baseline]:[])].map((item,index)=><tr key={index}><td>{index?"Baseline":"Current"}</td><td>{item.lotId} / {item.waferId}</td><td>{item.parts.length.toLocaleString("en-US")}</td><td>{(yieldOf(item)*100).toFixed(2)}%</td><td>{item.parts.filter(part=>!part.pass).length.toLocaleString("en-US")}</td></tr>)}</tbody></table></div><p className="comparison-note">PRR pass rate uses the parsed pass flag across all part records; repeated records are retained.</p></article>
    <article className="panel comparison-table"><div className="panel-head"><h2>Test comparison</h2></div><div className="table-wrap comparison-test-scroll"><table><thead><tr><th>Test #</th><th>Name</th><th>Unit</th><th>Current mean</th><th>Baseline mean</th><th>Mean difference</th><th>Current Fail %</th></tr></thead><tbody>{comparisons.map(item=><tr key={item.test.id}><td><button type="button" className="comparison-test-link" onClick={()=>{setSelectedTestId(item.test.id);setView("tests")}}>{item.test.id}</button></td><td>{item.test.name}</td><td>{item.test.unit||"—"}</td><td>{formatNumber(item.currentStats.mean,6)}</td><td>{item.previousStats?formatNumber(item.previousStats.mean,6):"—"}</td><td>{item.delta===null?"—":formatNumber(item.delta,6)}</td><td>{(item.currentStats.failRate*100).toFixed(2)}%</td></tr>)}</tbody></table></div><p className="comparison-note">Means use each run&apos;s full test population. Tests with different units are not compared.</p></article>
    <details className="workspace-advanced" open={showCorrelation} onToggle={event=>setShowCorrelation(event.currentTarget.open)}><summary>Advanced · matched-die correlation</summary>{showCorrelation&&<div className="comparison-correlation"><label>Test <select aria-label="Correlation test" value={focused?.test.id??""} onChange={event=>setFocusedTestId(Number(event.target.value))}>{comparisons.map(item=><option key={item.test.id} value={item.test.id}>{item.test.id} · {item.test.name}</option>)}</select></label><p>Match unique X / Y coordinates within the same recorded lot and wafer. Ambiguous repeats and missing coordinates are excluded.</p>{pairing?.reason?<p role="status">{pairing.reason}</p>:<><div className="correlation-kpis"><div><span>PAIRED RECORDS</span><b>{correlation.n}</b></div><div><span>R</span><b>{correlation.r===null?"—":formatNumber(correlation.r,4)}</b></div><div><span>R²</span><b>{correlation.r2===null?"—":formatNumber(correlation.r2,4)}</b></div></div><div className="correlation-plot"><CorrelationScatter pairs={pairing?.pairs??[]} result={correlation}/></div></>}{pairing&&<p>{pairing.excludedCurrentMeasurements} current / {pairing.excludedPreviousMeasurements} baseline measurements excluded.</p>}</div>}</details>
  </section>;
}

type ParetoDatum={label:string;detail:string;count:number};
function ParetoChart({data,total,ariaLabel}:{data:ParetoDatum[];total:number;ariaLabel:string}){if(!data.length)return <div className="pareto-empty">No failed PRR records in this run.</div>;const sorted=[...data].sort((a,b)=>b.count-a.count),shown=sorted.length<=6?sorted:[...sorted.slice(0,5),{label:"OTHER",detail:`${sorted.length-5} remaining causes`,count:sorted.slice(5).reduce((sum,item)=>sum+item.count,0)}],peak=maximum([...shown.map(item=>item.count),1]),slot=440/shown.length,barWidth=Math.min(48,slot*.62),cumulative=shown.map((_,index)=>shown.slice(0,index+1).reduce((sum,item)=>sum+item.count,0)/Math.max(total,1)*100),points=cumulative.map((value,index)=>`${62+slot*(index+.5)},${218-value/100*164}`).join(" ");return <div className="jmp-pareto" aria-label={ariaLabel}><JmpReportTitle title="Pareto Plot" subtitle="Count and cumulative percent"/><svg viewBox="0 0 560 270" role="img"><rect x="62" y="54" width="440" height="164" className="jmp-plot-frame"/>{[0,.25,.5,.75,1].map(t=><g key={t}><line x1="62" x2="502" y1={218-t*164} y2={218-t*164} className="grid-line"/><text x="53" y={222-t*164} textAnchor="end" className="axis-label">{Math.round(peak*t)}</text><text x="511" y={222-t*164} className="axis-label">{Math.round(t*100)}%</text></g>)}{shown.map((item,index)=>{const x=62+slot*(index+.5),height=item.count/peak*164,label=item.label.length>13?`${item.label.slice(0,12)}…`:item.label,detail=item.detail.length>15?`${item.detail.slice(0,14)}…`:item.detail;return <g key={`${item.label}-${index}`}><rect x={x-barWidth/2} y={218-height} width={barWidth} height={height} className="jmp-pareto-bar"><title>{`${item.label} · ${item.detail} · ${item.count} dies · ${(item.count/Math.max(total,1)*100).toFixed(1)}%`}</title></rect><text x={x} y={Math.max(49,212-height)} textAnchor="middle" className="pareto-value">{item.count}</text><text x={x} y="236" textAnchor="middle" className="pareto-axis-label"><tspan x={x}>{label}</tspan><tspan x={x} dy="12">{detail}</tspan></text></g>})}<polyline points={points} className="jmp-pareto-line"/>{cumulative.map((value,index)=><circle key={index} cx={62+slot*(index+.5)} cy={218-value/100*164} r="3" className="jmp-pareto-point"><title>{`Cumulative ${value.toFixed(1)}%`}</title></circle>)}<line x1="62" x2="502" y1="218" y2="218" className="axis-line"/><line x1="62" x2="62" y1="54" y2="218" className="axis-line"/><line x1="502" x2="502" y1="54" y2="218" className="axis-line"/></svg></div>}
function BinPareto({run}:{run:RunData}){const counts=new Map<number,number>();run.parts.filter(part=>!part.pass).forEach(part=>counts.set(part.hardBin,(counts.get(part.hardBin)||0)+1));const data=[...counts.entries()].map(([bin,count])=>({label:`HB${bin}`,detail:"Recorded hard bin",count}));return <ParetoChart data={data} total={run.parts.filter(part=>!part.pass).length} ariaLabel="Hard bin Pareto with cumulative percentage"/>}
function FirstFailPareto({run}:{run:RunData}){const failedParts=run.parts.filter(part=>!part.pass),testsById=new Map(run.tests.map(test=>[test.id,test])),counts=new Map<number|null,number>();failedParts.forEach(part=>counts.set(part.firstFailTestId,(counts.get(part.firstFailTestId)||0)+1));const data=[...counts.entries()].map(([testId,count])=>({label:testId===null?"UNCLASSIFIED":`T${testId}`,detail:testId===null?"No failing PTR":testsById.get(testId)?.name||"Unknown test",count}));return <ParetoChart data={data} total={failedParts.length} ariaLabel="First failing PTR per failed PRR record"/>}
function YieldLine({run}:{run:RunData}){const series=useMemo(()=>{const stride=Math.max(1,Math.ceil(run.parts.length/60)),points:Array<{index:number;value:number}>=[];let passed=0;run.parts.forEach((part,index)=>{if(part.pass)passed++;if(index%stride===stride-1||index===run.parts.length-1)points.push({index,value:passed/(index+1)*100})});return points},[run]);if(!run.parts.length)return <PlotEmpty message="No completed devices are available."/>;const rawMin=minimum([...series.map(point=>point.value)]),rawMax=maximum([...series.map(point=>point.value)]),min=Math.max(0,Math.floor(rawMin-2)),max=Math.min(100,Math.ceil(rawMax+2)),spread=max-min||1,x=(index:number)=>50+index/Math.max(run.parts.length-1,1)*320,y=(value:number)=>112-(value-min)/spread*82,poly=series.map(point=>`${x(point.index)},${y(point.value)}`).join(" ");return <svg className="yield-line jmp-yield-line" viewBox="0 0 400 135" role="img" aria-label="Cumulative PRR pass rate by record sequence"><rect x="50" y="30" width="320" height="82" className="jmp-plot-frame"/>{[0,.5,1].map(t=><g key={t}><line x1="50" x2="370" y1={112-t*82} y2={112-t*82} className="grid-line"/><text x="43" y={116-t*82} textAnchor="end" className="axis-label">{formatNumber(min+t*spread,1)}%</text></g>)}<polyline points={poly} className="jmp-yield-series"/><circle cx={x(series.at(-1)!.index)} cy={y(series.at(-1)!.value)} r="3.2" className="jmp-yield-point"/><line x1="50" x2="370" y1="112" y2="112" className="axis-line"/><line x1="50" x2="50" y1="30" y2="112" className="axis-line"/></svg>}
