export default function Home(){
  const [view,setViewState]=useState<ViewKey>("overview"),[run,setRun]=useState<RunData|null>(null),[history,setHistory]=useState<RunData[]>([]);
  const setView=useCallback((next:ViewKey)=>{trackUsageFeature(next);setViewState(next)},[]);
  const [selectedTestId,setSelectedTestId]=useState<number|null>(null),[plot,setPlot]=useState<PlotKey>("distribution"),[site,setSite]=useState<number|"all">("all"),[search,setSearch]=useState(""),[testFilter,setTestFilter]=useState<TestFilter>("all");
  const [dragging,setDragging]=useState(false),[loading,setLoading]=useState(false),[notice,setNotice]=useState<{message:string;kind:"info"|"error"|"warning"}|null>(null),[mobileNav,setMobileNav]=useState(false),[runMenu,setRunMenu]=useState(false),[runRevision,setRunRevision]=useState(0);
  const [recordFamily,setRecordFamily]=useState<RecordFamily>("PTR");
  const [progress,setProgress]=useState({fileName:"",index:0,total:0,fraction:0});
  const fileInput=useRef<HTMLInputElement>(null),folderInput=useRef<HTMLInputElement>(null),loadController=useRef<AbortController|null>(null);
  const openFiles=useCallback(()=>fileInput.current?.click(),[]);
  useEffect(()=>()=>loadController.current?.abort(),[]);
  const notify=(message:string,kind:"info"|"error"|"warning"="info")=>setNotice({message,kind});
  const summaries=useMemo(()=>new Map(run?.tests.map(test=>[test.id,stats(test)])??[]),[run]);
  const typedByKind=useMemo(()=>({FTR:run?.typedTests?.filter(test=>test.kind==="FTR")??emptyTypedTests,MPR:run?.typedTests?.filter(test=>test.kind==="MPR")??emptyTypedTests}),[run]);
  const selectParametricTest=useCallback((id:number)=>{setSelectedTestId(id);setRecordFamily("PTR")},[]);
  const selectedTest=run?(run.tests.find(t=>t.id===selectedTestId)||run.tests[0]):null,selectedStats=selectedTest?summaries.get(selectedTest.id)??null:null;
  const filteredTests=useMemo(()=>run?run.tests.filter(test=>{const matchesSearch=`${test.id} ${test.name}`.toLowerCase().includes(search.toLowerCase()),summary=summaries.get(test.id)!;return matchesSearch&&(testFilter==="all"||(testFilter==="failing"&&summary.failRate>0)||(testFilter==="review"&&summary.cpk!==null&&Number.isFinite(summary.cpk)&&summary.cpk<1.33)||(testFilter==="unavailable"&&(summary.cpk===null||!Number.isFinite(summary.cpk)))||(testFilter==="capable"&&summary.cpk!==null&&summary.cpk>=1.33))}):[],[run,search,testFilter,summaries]);
  const {totalYield,failCount,sites}=useMemo(()=>{
    let passed=0;const detectedSites=new Set<number>();
    for(const part of run?.parts??[]){if(part.pass)passed++;detectedSites.add(part.site)}
    const count=run?.parts.length??0;
    return{totalYield:passed/Math.max(count,1),failCount:count-passed,sites:[...detectedSites].sort((a,b)=>a-b)};
  },[run]);
  const cancelLoad=()=>{loadController.current?.abort();loadController.current=null;setLoading(false)};
  const activateRun=(next:RunData)=>{setRun(next);setSelectedTestId(next.tests[0]?.id??null);setRecordFamily(next.tests.length?"PTR":next.typedTests?.some(test=>test.kind==="FTR")?"FTR":next.typedTests?.some(test=>test.kind==="MPR")?"MPR":"PTR");setSite("all");setSearch("");setTestFilter("all");setPlot("distribution");setViewState("tests");setRunMenu(false);setMobileNav(false);setRunRevision(value=>value+1)};
  const loadSample=()=>{cancelLoad();const sample=createDemoRun();setHistory(prev=>[...(run?[run]:[]),...prev].slice(0,24));activateRun(sample);notify("Synthetic sample run loaded. No file was uploaded.")};
  const clearWorkspace=()=>{cancelLoad();setRun(null);setHistory([]);setSelectedTestId(null);setRecordFamily("PTR");setSearch("");setSite("all");setTestFilter("all");setPlot("distribution");setViewState("overview");setRunMenu(false);setMobileNav(false);setRunRevision(value=>value+1);notify("Workspace cleared. Local files have not been changed.")};
  const loadFiles=async(files:File[])=>{
    if(!files.length)return;
    cancelLoad();
    const supported=files.filter(file=>/\.(stdf|std)(\.gz)?$/i.test(file.name)),candidates=supported.slice(0,24);
    if(!candidates.length){trackUsageError("load_error");notify("No STDF or compressed STDF files were found.","error");return}
    const controller=new AbortController();loadController.current=controller;setLoading(true);setNotice(null);
    const parsed:RunData[]=[],errors:string[]=[],loadStarted=performance.now();
    try{
      for(const [index,file] of candidates.entries()){
        controller.signal.throwIfAborted();setProgress({fileName:file.name,index:index+1,total:candidates.length,fraction:0});let lastProgressPaint=performance.now();
        try{parsed.push(await parseStdfFile(file,{signal:controller.signal,onProgress:fraction=>{const now=performance.now();if(loadController.current===controller&&(fraction>=1||now-lastProgressPaint>=100)){lastProgressPaint=now;setProgress({fileName:file.name,index:index+1,total:candidates.length,fraction})}}}))}
        catch(error){if(controller.signal.aborted)throw error;errors.push(`${file.name}: ${error instanceof Error?error.message:"Could not parse file"}`)}
      }
      if(loadController.current!==controller||controller.signal.aborted)return;
      const latest=parsed.at(-1);
      if(errors.length||!latest)trackUsageError("load_error");
      if(!latest){notify(errors.join(" ")||"Could not parse the selected STDF files.","error");return}
      setHistory(prev=>[...(run?[run]:[]),...parsed.slice(0,-1),...prev].slice(0,24));activateRun(latest);
      trackUsageFeature("load_success");
      const skipped=files.length-candidates.length,loadSeconds=(performance.now()-loadStarted)/1000;
      notify(`${parsed.length} STDF run${parsed.length>1?"s":""} parsed locally — ${parsed.reduce((n,r)=>n+r.parts.length,0).toLocaleString("en-US")} devices. Local read and parse: ${loadSeconds.toFixed(1)} s.${skipped?` ${skipped} file(s) skipped (unsupported type or 24-file limit).`:""}${errors.length?` Skipped: ${errors.join(" ")}`:""}`,errors.length||skipped?"warning":"info");
    }catch(error){if(!controller.signal.aborted&&loadController.current===controller){trackUsageError("load_error");notify(error instanceof Error?error.message:"Could not parse these files.","error")}}
    finally{if(loadController.current===controller){loadController.current=null;setLoading(false)}}
  };
  const collectFolder=async(handle:DirectoryHandleWithEntries,files:File[],signal:AbortSignal)=>{
    for await(const entry of handle.values()){
      signal.throwIfAborted();if(files.length>=24)break;
      if(entry.kind==="file"&&/\.(stdf|std)(\.gz)?$/i.test(entry.name))files.push(await entry.getFile());
      else if(entry.kind==="directory")await collectFolder(entry,files,signal);
    }
  };
  const openFolder=async()=>{
    const picker=(window as Window&{showDirectoryPicker?:(options?:{mode?:"read"})=>Promise<DirectoryHandleWithEntries>}).showDirectoryPicker;
    if(!picker){folderInput.current?.click();return}
    cancelLoad();const controller=new AbortController();loadController.current=controller;
    try{
      const handle=await picker({mode:"read"}),files:File[]=[];
      controller.signal.throwIfAborted();setLoading(true);setNotice(null);setProgress({fileName:"Scanning folder",index:0,total:0,fraction:0});
      await collectFolder(handle,files,controller.signal);controller.signal.throwIfAborted();
      if(files.length)await loadFiles(files);else{trackUsageError("load_error");notify("No STDF or compressed STDF files were found in this folder.","error")}
    }catch(error){if(controller.signal.aborted||error instanceof DOMException&&error.name==="AbortError")return;trackUsageError("load_error");notify(error instanceof Error?error.message:"Could not open this folder.","error")}
    finally{if(loadController.current===controller){loadController.current=null;setLoading(false)}}
  };

  const onFile=(event:ChangeEvent<HTMLInputElement>)=>{void loadFiles([...event.target.files||[]]);event.target.value=""},onFolder=onFile,onDrop=(event:DragEvent)=>{event.preventDefault();setDragging(false);void loadFiles([...event.dataTransfer.files])};
  // Loading progress does not change an existing analysis. Keep its charts and
  // tables mounted without rebuilding thousands of SVG cells on each update.
  const coverage=useMemo(()=>run?<RecordCoveragePanel key={`coverage-${runRevision}`} run={run}/>:null,[run,runRevision]);
  const analysis=useMemo(()=>run?<>
    {view==="overview"?(selectedTest?<Overview run={run} totalYield={totalYield} failCount={failCount} sites={sites} setView={setView}/>:<RecordOnlyOverview run={run} setView={setView}/>):view==="tests"?<div className="test-family-workspace">
        <RecordFamilySwitch run={run} family={recordFamily} setFamily={setRecordFamily}/>
        {selectedTest&&selectedStats?<div className="typed-family-panel" hidden={recordFamily!=="PTR"}><EnhancedTestExplorer key={runRevision} summaries={summaries} run={run} test={selectedTest} testStats={selectedStats} filteredTests={filteredTests} search={search} setSearch={setSearch} selectedTestId={selectedTestId??selectedTest.id} setSelectedTestId={selectParametricTest} sites={sites} site={site} setSite={setSite} plot={plot} setPlot={setPlot} setView={setView} testFilter={testFilter} setTestFilter={setTestFilter}/></div>:recordFamily==="PTR"&&<section className="page-content"><div className="typed-empty"><h2>No PTR measurements in this run</h2><p>Choose FTR or MPR above to inspect decoded records. Wafer pass/fail and hard-bin views use the original PRR parts.</p></div></section>}
        {recordFamily!=="PTR"&&<div className="page-content typed-family-page"><TypedTestExplorer key={String(runRevision)+recordFamily} run={run} tests={typedByKind[recordFamily]}/></div>}
      </div>:view==="wafer"?<WaferPage key={`wafer-${runRevision}`} run={run} test={selectedTest??undefined} testStats={selectedStats??undefined} onOpenTest={id=>{selectParametricTest(id);setView("tests")}} setSelectedTestId={selectParametricTest}/>:run.tests.length?<EnhancedComparePage run={run} history={history} openFiles={openFiles} setSelectedTestId={selectParametricTest} setView={setView}/>:<RecordOnlyOverview run={run} setView={setView} history={history}/>}
    {coverage}
  </>:null,[coverage,run,runRevision,view,selectedTest,selectedStats,totalYield,failCount,sites,setView,recordFamily,summaries,filteredTests,search,selectedTestId,selectParametricTest,site,plot,testFilter,typedByKind,history,openFiles]);
  const nav:Array<{key:ViewKey;label:string;icon:IconName}>=[{key:"overview",label:"Run overview",icon:"overview"},{key:"tests",label:"Test explorer",icon:"tests"},{key:"wafer",label:"Wafer map",icon:"wafer"},{key:"compare",label:"Compare runs",icon:"compare"}];
  return <div className={`app-shell${run?" analysis-active":""}`} onDragEnter={event=>{if(event.dataTransfer.types.includes("Files"))setDragging(true)}} onDragOver={e=>e.preventDefault()} onDrop={onDrop}>
    {dragging&&<div className="drop-overlay" onDragLeave={()=>setDragging(false)}><div><Icon name="upload" size={30}/><strong>Drop STDF files to analyze</strong><span>Files stay on this device</span></div></div>}
    {run&&mobileNav&&<button type="button" className="navigation-backdrop" aria-label="Close navigation overlay" onClick={()=>setMobileNav(false)}/>}
    <aside className={`sidebar ${mobileNav?"open":""}`} inert={!!run&&!mobileNav} aria-hidden={!!run&&!mobileNav}><div className="brand"><div className="brand-mark" aria-hidden="true">{Array.from({length:4},(_,i)=><i key={i}/>)}</div><div><b>STDF INSIGHT</b><span>TEST ANALYTICS</span></div><button className="nav-close" onClick={()=>setMobileNav(false)} aria-label="Close navigation"><Icon name="close"/></button></div><div className="workspace-label">ANALYSIS WORKSPACE <span>V4</span></div><nav>{nav.map(item=><button key={item.key} className={view===item.key?"active":""} disabled={!run} aria-current={view===item.key?"page":undefined} onClick={()=>{setView(item.key);setMobileNav(false)}}><Icon name={item.icon}/><span>{item.label}</span>{item.key==="tests"&&<em>{(run?.tests.length??0)+(run?.typedTests?.length??0)}</em>}</button>)}</nav><a className="about-nav-link" href="/about"><span aria-hidden="true">TC</span><b>About the author</b></a><a className="about-nav-link" href="/feedback?lang=en"><span aria-hidden="true">＋</span><b>Feedback &amp; wishes</b></a><div className="side-separator"/><div className="side-heading"><span>ACTIVE RUN</span><button aria-label="Run options" aria-expanded={runMenu} disabled={!run} onClick={()=>setRunMenu(value=>!value)}>•••</button></div>{run&&runMenu&&<div className="run-menu"><button onClick={()=>{exportRun(run);setRunMenu(false)}}><Icon name="download" size={14}/>Export summary</button><button onClick={()=>{setHistory([]);setRunMenu(false);notify("Recent run history cleared.")}}><Icon name="close" size={14}/>Clear recent runs</button><button onClick={clearWorkspace}><Icon name="close" size={14}/>Clear workspace</button></div>}{run?<button className="active-file" onClick={()=>setView("overview")}><span className="file-icon"><Icon name="file"/></span><span><b>{run.lotId} · {run.waferId}</b><small>{run.fileName}</small></span><i/></button>:<div className="empty-active-file"><span className="file-icon"><Icon name="upload"/></span><span><b>No run loaded</b><small>Open an STDF file to begin</small></span></div>}{history.slice(0,4).map((item,i)=><button className="recent-file" key={`${item.fileName}${i}`} onClick={()=>{cancelLoad();setHistory(prev=>[...(run?[run]:[]),...prev.filter(r=>r!==item)].slice(0,24));activateRun(item)}}><Icon name="file"/><span>{item.lotId} · {item.waferId}</span></button>)}<div className="sidebar-bottom"><div className="local-badge"><span className="pulse"/><div><b>Browser-local analysis</b><small>STDF data stays on this PC</small></div></div><a className="user-chip" href="https://www.linkedin.com/in/tim-chang-56bb1992/" target="_blank" rel="noreferrer" aria-label="Open Tim Chang's LinkedIn profile"><span>TC</span><div><b>Tim Chang</b><small>View on LinkedIn</small></div></a></div></aside>
    <main className="main-stage"><header className="topbar"><div className="topbar-left"><button className="menu-button" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Icon name="menu"/></button><div className="crumb"><span>{view==="overview"?"RUNS":view.toUpperCase()}</span><Icon name="chevron" size={13}/><b>{run?`${run.lotId} / ${run.waferId}`:"No run loaded"}</b></div><span className="run-status"><i/> {run?"sensing analytics ready":"waiting for STDF"}</span></div><div className="top-actions">{run&&<nav className="run-view-tabs" aria-label="Workspace views">{([{key:"tests",label:"Analysis"},{key:"wafer",label:"Wafer"},{key:"compare",label:"Compare"},{key:"overview",label:"Overview"}] as Array<{key:ViewKey;label:string}>).map(item=><button type="button" key={item.key} aria-current={view===item.key?"page":undefined} onClick={()=>setView(item.key)}>{item.label}</button>)}</nav>}<button className="secondary-button sample-button" onClick={loadSample}><Icon name="spark"/> Sample run</button><button className="secondary-button folder-button" onClick={()=>void openFolder()} disabled={loading}><Icon name="folder"/>Open folder</button><button className="upload-button" onClick={()=>fileInput.current?.click()} disabled={loading}><Icon name="upload"/>{loading?"Parsing…":"Open STDF"}</button><input ref={fileInput} type="file" multiple accept=".stdf,.std,.stdf.gz,.std.gz,application/gzip" onChange={onFile} hidden/><input ref={folderInput} type="file" multiple onChange={onFolder} hidden {...({webkitdirectory:"",directory:""} as Record<string,string>)}/></div></header>{loading&&<div className="load-progress" role="status"><div><b>{progress.total?`Reading ${progress.index} of ${progress.total}`:"Finding STDF files"}</b><span title={progress.fileName}>{progress.fileName}</span></div><progress max={1} value={progress.total?(progress.index-1+progress.fraction)/progress.total:0} aria-label="STDF loading progress"/><button onClick={()=>{cancelLoad();notify("Loading cancelled. Your current workspace is unchanged.")}}>Cancel loading</button></div>}{notice&&<div className={`notice ${notice.kind}`} role={notice.kind==="error"?"alert":"status"}><span>{notice.message}</span><button onClick={()=>setNotice(null)} aria-label="Dismiss"><Icon name="close" size={15}/></button></div>}
      {run?analysis:<EmptyState loading={loading} openFiles={openFiles} openFolder={()=>void openFolder()} loadSample={loadSample}/>}
      {!run&&<AuthorFooter/>}</main>
  </div>
}

function AuthorFooter(){return <SiteFooter/>}

function EmptyState({loading,openFiles,openFolder,loadSample}:{loading:boolean;openFiles:()=>void;openFolder:()=>void;loadSample:()=>void}){return <section className="page-content empty-page"><article className="empty-panel"><div><span className="eyebrow">STDF ANALYSIS WORKSPACE</span><h1>Open an STDF file to begin</h1><p>Drop STDF or STDF.gz files here. Analysis stays in your browser.</p></div><div className="empty-actions"><button className="upload-button" onClick={openFiles} disabled={loading}><Icon name="upload"/>{loading?"Parsing...":"Open STDF"}</button><button className="secondary-button" onClick={openFolder} disabled={loading}><Icon name="folder"/>Open folder</button><button className="secondary-button" onClick={loadSample} disabled={loading}><Icon name="spark"/>Sample run</button></div></article></section>}

function RecordFamilySwitch({run,family,setFamily}:{run:RunData;family:RecordFamily;setFamily:(family:RecordFamily)=>void}){
  const families=useMemo(()=>[
    {key:"PTR" as const,title:"PTR · Parametric",tests:run.tests.length,records:run.tests.reduce((sum,test)=>sum+test.values.length,0)},
    ...(["FTR","MPR"] as const).map(kind=>{const tests=run.typedTests?.filter(test=>test.kind===kind)??[];return{key:kind,title:kind==="FTR"?"FTR · Functional":"MPR · Multiple-return",tests:tests.length,records:tests.reduce((sum,test)=>sum+test.observations.length,0)}}),
  ],[run]);
  return <div className="typed-family-navigation"><div className="typed-family-buttons" role="group" aria-label="Test record family">{families.filter(item=>item.tests>0||item.key===family).map(item=><button key={item.key} type="button" aria-pressed={family===item.key} onClick={()=>setFamily(item.key)}><b>{item.title}</b><span>{item.tests.toLocaleString("en-US")} tests · {item.records.toLocaleString("en-US")} records</span></button>)}</div></div>
}

function RecordOnlyOverview({run,setView,history}:{run:RunData;setView:(view:ViewKey)=>void;history?:RunData[]}){
  const typed=run.typedTests??[],ftr=typed.filter(test=>test.kind==="FTR"),mpr=typed.filter(test=>test.kind==="MPR"),recordCount=(tests:TypedTest[])=>tests.reduce((sum,test)=>sum+test.observations.length,0),linked=new Set(typed.flatMap(test=>test.observations.flatMap(observation=>observation.partIndex===null?[]:[observation.partIndex])));
  return <section className="page-content typed-run-overview"><div className="lab-hero-strip"><div><span>STDF INSIGHT</span><b>Local record inspection</b></div></div><div className="section-title"><div><span className="eyebrow">{history?"LOADED RUNS":"STDF ANALYSIS WORKSPACE"}</span><h1>{history?"Run records":run.lotId}</h1><p>{run.fileName} · wafer {run.waferId}</p></div></div><div className="metrics-grid"><Metric label="PRR PART RECORDS" value={run.parts.length.toLocaleString("en-US")} detail="Original part records retained" tone="mint"/><Metric label="FTR RECORDS" value={recordCount(ftr).toLocaleString("en-US")} detail={`${ftr.length} functional tests`} tone="blue"/><Metric label="MPR RECORDS" value={recordCount(mpr).toLocaleString("en-US")} detail={`${mpr.length} multiple-return tests`} tone="amber"/><Metric label="COVERED PRR PARTS" value={linked.size.toLocaleString("en-US")} detail="Distinct linked part indexes" tone="rose"/></div><article className="panel typed-run-record-panel"><h2>{history?"Parametric comparison is unavailable for this run":"This run has no PTR measurements"}</h2><p>Decoded FTR and MPR records remain available in Test explorer. Record verdicts, raw / effective fields, return arrays and source references can be inspected without inventing numeric samples or per-result outcomes.</p><p>Wafer pass/fail and hard-bin views use the original PRR records. Coverage counts are not an execution rate.</p><div><button className="upload-button" onClick={()=>setView("tests")}>Inspect test records <Icon name="chevron" size={14}/></button><button className="secondary-button" onClick={()=>setView("wafer")}>Open wafer map <Icon name="wafer" size={16}/></button></div></article>{history&&<article className="panel typed-run-record-panel"><h2>Loaded run coverage</h2><div className="typed-table-scroll" role="region" aria-label="Loaded run coverage" tabIndex={0}><table><thead><tr><th>File</th><th>PRR parts</th><th>PTR tests</th><th>FTR records</th><th>MPR records</th></tr></thead><tbody>{[run,...history].map((item,index)=><tr key={index}><td>{item.fileName}</td><td>{item.parts.length.toLocaleString("en-US")}</td><td>{item.tests.length.toLocaleString("en-US")}</td><td>{recordCount(item.typedTests?.filter(test=>test.kind==="FTR")??[]).toLocaleString("en-US")}</td><td>{recordCount(item.typedTests?.filter(test=>test.kind==="MPR")??[]).toLocaleString("en-US")}</td></tr>)}</tbody></table></div></article>}</section>
}


function Overview({run,totalYield,failCount,sites,setView}:{run:RunData;totalYield:number;failCount:number;sites:number[];setView:(v:ViewKey)=>void}){
  const[paretoMode,setParetoMode]=useState<ParetoMode>("first-fail");
  return <section className="page-content overview-page">
    <div className="lab-hero-strip"><div><span>STDF INSIGHT</span><b>Local semiconductor test analytics</b></div></div>
    <div className="run-heading"><div><div className="eyebrow"><span>STDF ANALYSIS WORKSPACE</span><span className="source-tag">{run.source==="demo"?"DEMO DATA":"LOCAL FILE"}</span></div><h1>{run.lotId} <span>/</span> {run.waferId}</h1><p>{run.device} · {run.program}</p></div><div className="run-meta"><div><span>TESTER</span><b>{run.tester}</b></div><div><span>STARTED</span><b>{run.startTime.toLocaleString("en-US",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit",hour12:false,timeZone:"Asia/Taipei"})}</b></div><div><span>DURATION</span><b>{Math.max(1,Math.round((run.finishTime.getTime()-run.startTime.getTime())/60000))} min</b></div><button aria-label="Export report" onClick={()=>exportRun(run)}><Icon name="download"/></button></div></div>
    <div className="metrics-grid"><Metric label="PRR PASS RATE" value={`${(totalYield*100).toFixed(2)}%`} detail={`${run.parts.filter(p=>p.pass).length.toLocaleString("en-US")} / ${run.parts.length.toLocaleString("en-US")} devices`} tone="mint"/><Metric label="FAILED PRR RECORDS" value={failCount.toLocaleString("en-US")} detail={`${(100-totalYield*100).toFixed(2)}% fallout`} tone="rose"/><Metric label="PTR TEST COUNT" value={run.tests.length.toLocaleString("en-US")} detail={`${sites.length} parallel sites`} tone="blue"/><Metric label="MEDIAN TEST TIME" value={`${formatNumber(percentile(run.parts.map(p=>p.testTimeMs),.5),0)} ms`} detail={`P95 ${formatNumber(percentile(run.parts.map(p=>p.testTimeMs),.95),0)} ms`} tone="amber"/></div>
    <div className="overview-grid">
      <article className="panel yield-panel"><div className="panel-head"><div><span className="panel-kicker">CURRENT RUN HEALTH</span><h2>Cumulative PRR pass rate</h2></div><div className="legend"><i className="mint-dot"/> PRR pass · record sequence</div></div><div className="yield-big"><strong>{(totalYield*100).toFixed(2)}%</strong><span>{run.parts.length.toLocaleString("en-US")} <small>part records</small></span></div><YieldLine run={run}/><div className="yield-axis"><span>1</span><span>25%</span><span>50%</span><span>75%</span><b>{run.parts.length.toLocaleString("en-US")}</b></div></article>
      <article className="panel wafer-panel"><div className="panel-head"><div><span className="panel-kicker">SPATIAL SENSING VIEW</span><h2>Wafer health</h2></div><button className="text-button" onClick={()=>setView("wafer")}>Open map <Icon name="chevron" size={14}/></button></div><div className="wafer-compact-wrap"><WaferMap run={run} compact mode="passfail"/></div></article>
      <article className="panel pareto-panel"><div className="panel-head"><div><span className="panel-kicker">FAILED PRR RECORDS</span><h2>{paretoMode==="first-fail"?"First fail test Pareto":"Hard bin Pareto"}</h2></div><div className="pareto-mode-switch" role="group" aria-label="Pareto type"><button className={paretoMode==="first-fail"?"active":""} onClick={()=>setParetoMode("first-fail")}>First fail</button><button className={paretoMode==="hard-bin"?"active":""} onClick={()=>setParetoMode("hard-bin")}>Hard bin</button></div></div><div className="pareto-summary">{failCount.toLocaleString("en-US")} failed PRR records · repeated coordinates retained</div>{paretoMode==="first-fail"?<FirstFailPareto run={run}/>:<BinPareto run={run}/>}<button className="panel-action" onClick={()=>setView("tests")}>Investigate failing tests <Icon name="chevron" size={14}/></button></article>
      <article className="panel site-panel"><div className="panel-head"><div><span className="panel-kicker">MULTI-SITE BALANCE</span><h2>Site health</h2></div><span className="quality-chip">{sites.length} SITES</span></div><div className="site-list">{sites.map(s=>{const siteParts=run.parts.filter(p=>p.site===s),y=siteParts.filter(p=>p.pass).length/siteParts.length*100;return <div className="site-row" key={s}><b>S{s}</b><span className="site-track"><i style={{width:`${y}%`}}/></span><strong>{y.toFixed(2)}%</strong><small>{siteParts.length} units</small></div>})}</div><div className="site-note"><Icon name="check" size={15}/><span>PRR pass rate by site; repeated records retained</span></div></article>
    </div>
  </section>
}



function WaferPage({run,test,testStats,setSelectedTestId,onOpenTest}:{run:RunData;test?:TestData;testStats?:ReturnType<typeof stats>;setSelectedTestId:(v:number)=>void;onOpenTest:(id:number)=>void}){
  const[mapMode,setMapMode]=useState<MapMode>("passfail"),sites=[...new Set(run.parts.map(part=>part.site))].sort((a,b)=>a-b),dieLabel=run.waferGeometry?.dieWidth&&run.waferGeometry?.dieHeight?`${formatNumber(run.waferGeometry.dieWidth,3)} x ${formatNumber(run.waferGeometry.dieHeight,3)}`:"N/A";
  const shownMode=mapMode==="parametric"&&!test?"passfail":mapMode;
  return <section className="page-content wafer-page"><div className="section-title"><div><span className="eyebrow">SPATIAL SIGNATURE</span><h1>Wafer map</h1><p>{test?"Switch between parametric values, hard bins and pass/fail disposition.":"Review the original PRR pass/fail disposition and hard bins. No PTR test is available for a parametric color map."}</p></div><div className="map-mode">{(["parametric","bin","passfail"] as MapMode[]).map(mode=><button key={mode} className={shownMode===mode?"active":""} disabled={mode==="parametric"&&!test} title={mode==="parametric"&&!test?"A PTR test is required for parametric colors":undefined} onClick={()=>setMapMode(mode)}>{mode==="parametric"?"Parametric":mode==="bin"?"Bin map":"Pass / fail"}</button>)}</div></div><div className="wafer-workspace"><article className="panel full-wafer"><div className="wafer-toolbar"><div><span>{test?"SELECTED PTR TEST":"RECORD DISPOSITION"}</span>{test?<select aria-label="Select wafer map test" value={test.id} onChange={e=>setSelectedTestId(Number(e.target.value))}>{run.tests.map(t=><option value={t.id} key={t.id}>{t.id} · {t.name}</option>)}</select>:<p className="typed-wafer-no-ptr">PRR pass/fail and hard-bin mapping remain available.</p>}</div><div className="map-info"><span>WAFER <b>{run.waferId}</b></span><span>SITES <b>{sites.length}</b></span><span>DIES <b>{run.parts.length.toLocaleString("en-US")}</b></span><span>DIE <b>{dieLabel}</b></span></div></div><div className="full-map-wrap"><WaferMap run={run} test={test} mode={shownMode} onSelectTest={onOpenTest}/></div></article><aside className="map-side"><article className="panel"><span className="panel-kicker">{test?"SELECTED PTR TEST":"AVAILABLE TEST RECORDS"}</span>{test&&testStats?<><h2>{test.name}</h2><div className="map-stat-grid"><div><span>Mean</span><b>{formatNumber(testStats.mean,4)}</b></div><div><span>σ</span><b>{formatNumber(testStats.sigma,4)}</b></div><div><span>Cpk</span><b>{testStats.cpk===null?"—":formatNumber(testStats.cpk,2)}</b></div><div><span>Fails</span><b>{test.values.filter(v=>!v.pass).length.toLocaleString("en-US")}</b></div></div></>:<><h2>No PTR measurements</h2><p className="typed-wafer-no-ptr">FTR and MPR records can be inspected in Test explorer. Overall die disposition comes from the PRR record.</p><div className="map-stat-grid"><div><span>FTR tests</span><b>{run.typedTests?.filter(item=>item.kind==="FTR").length??0}</b></div><div><span>MPR tests</span><b>{run.typedTests?.filter(item=>item.kind==="MPR").length??0}</b></div></div></>}</article></aside></div></section>
}


